mapper.insert:
 		insert into tbl_rental (
			mb_id
			, rt_days
			, rt_shipfee
			, rt_amount
			, rt_regdate
			, rt_payment
			, rt_state
			, rt_name
			, rt_zipcode
			, rt_addr
			, rt_tel
			, rt_req
			, rt_startdate
			, rt_enddate
			, rt_rtndate
			, rt_moddates
 		) values (
			#{mb_id}
			, #{rt_days}
			, #{rt_shipfee}
			, #{rt_amount}
			, #{rt_regdate}
			, #{rt_payment}
			, 0
			, #{rt_name}
			, #{rt_zipcode}
			, #{rt_addr}
			, #{rt_tel}
			, #{rt_req}
			, #{rt_startdate}
			, #{rt_enddate}
			, null
			, now()
 		)

 		insert into tbl_rentdetail (
	 		rt_no
	 		, rd_type
			, rd_serial
			, rd_price
			, rd_quantity
 		) values

 			 (#{item.rt_no}
	 			, #{item.rd_type}
				, #{item.rd_serial}
				, #{item.rd_price}
				, #{item.rd_quantity})
